	internal static string BuildDocument(StoreGameDetailData data, bool isAuthenticated, int? restoreScrollY = null, bool showInlineBackLink = false, StoreWebHomeContext? context = null)
	{
		IReadOnlyList<StoreProductGalleryItem> gallery = GetGallery(data);
		int activeEditionIndex = GetActiveEditionIndex(data);
		StoreProductEdition obj = ((data.Editions.Count == 0) ? null : data.Editions[Math.Clamp(activeEditionIndex, 0, data.Editions.Count - 1)]);
		string currentPriceText = obj?.CurrentPriceText ?? data.CurrentPriceText;
		string referencePriceText = obj?.ReferencePriceText ?? data.ReferencePriceText;
		string discountText = obj?.DiscountText ?? data.DiscountText;
		string editionNote = obj?.Note ?? data.EditionNote;
		string value = (((object)context == null) ? string.Empty : StoreWebHomeHtmlBuilder.RenderSharedHeader(context, "store"));
		return $"<!DOCTYPE html>\n<html lang=\"vi\">\n<head>\n<meta charset=\"utf-8\" />\n<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>{EncodeText(data.PageTitle)}</title>\n<style>\n{BuildStyles()}\n</style>\n</head>\n<body{(((object)context == null) ? string.Empty : " class=\"has-home-header\"")}>\n<div class=\"product-detail-page\" data-detail-root data-initial-edition=\"{activeEditionIndex}\" data-restore-scroll-y=\"{((restoreScrollY.HasValue && restoreScrollY.GetValueOrDefault() > 0) ? restoreScrollY.Value.ToString(CultureInfo.InvariantCulture) : string.Empty)}\">\n    {value}\n    <main class=\"product-page-main\">\n        {BuildInlineBackLink(data, showInlineBackLink)}\n        <section class=\"product-detail-section\" aria-labelledby=\"productTitle\">\n            <div class=\"container\">\n                <div class=\"product-detail-shell\">\n                    <div class=\"product-detail-main-column\">\n                        {BuildGallerySection(gallery)}\n                        {BuildPurchaseBar(data, currentPriceText, referencePriceText, discountText, editionNote)}\n                        {BuildPackageSection(data.PackageItems)}\n                        {BuildOverviewSection("Mô tả gói mua", data.PurchaseCardDescriptionHtml, data.PurchaseCardDescriptionText, "product-overview-card--purchase-description")}\n                        {BuildOverviewSection("Giới thiệu game này", data.AboutHtml, data.AboutText, null)}\n                        {BuildOverviewSection("Chi tiết nội dung", data.DetailedDescriptionHtml, data.DetailedDescriptionText, "product-overview-card--details")}\n                        {BuildRequirementsSection(data.Requirements)}\n                        {BuildOverviewSection("Review nổi bật trên Steam", data.SteamReviewsHtml, data.SteamReviewsText, "product-overview-card--steam-review")}\n                        {BuildYourReviewSection(isAuthenticated)}\n                        {BuildCustomerReviewsSection(data.CustomerReviews)}\n                    </div>\n\n                    <aside class=\"product-detail-sidebar\">\n                        <div class=\"product-summary\">\n                            <h1 id=\"productTitle\" class=\"product-summary-title\">{EncodeText(data.Name)}</h1>\n                            <div class=\"product-summary-cover\">\n                                <img src=\"{EncodeAttribute(data.CoverImageUrl)}\" alt=\"{EncodeAttribute(data.Name)}\" />\n                            </div>\n\n                            {BuildSummaryCopy(data.ShortDescription)}\n                            {BuildSummaryFacts(data.Facts)}\n\n                            <div class=\"product-age-card\">\n                                <div class=\"product-age-badge\">\n                                    <span class=\"product-age-letter\">{EncodeText(data.AgeLetter)}</span>\n                                    <span class=\"product-age-caption\">{EncodeText(data.AgeCaption)}</span>\n                                </div>\n\n                                <div class=\"product-age-copy\">\n                                    <strong>{EncodeText(data.StatusText)}</strong>\n                                    <span>{EncodeText(data.AgeDescription)}</span>\n                                </div>\n                            </div>\n\n                            {BuildSummaryTags(data.SummaryTags)}\n                        </div>\n                    </aside>\n                </div>\n            </div>\n        </section>\n\n        {BuildRelatedProductsSection(data.RelatedProducts)}\n    </main>\n</div>\n\n{BuildDetailToastHost()}\n{BuildOrderCheckoutModal()}\n{BuildLoadingOverlay()}\n<script>\n{BuildScript()}\n</script>\n</body>\n</html>";
	}

	private static IReadOnlyList<StoreProductGalleryItem> GetGallery(StoreGameDetailData data)
	{
		if (data.Gallery.Count > 0)
		{
			return data.Gallery;
		}
		return new _003C_003Ez__ReadOnlySingleElementList<StoreProductGalleryItem>(new StoreProductGalleryItem
		{
			ThumbnailUrl = data.CoverImageUrl,
			FullUrl = data.CoverImageUrl,
			Alt = data.Name,
			MainPosition = "center center"
		});
	}

