dth: 100%;\n    min-height: 52px;\n    border: none;\n    border-radius: var(--radius);\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n    padding: 0 16px;\n    color: #ffffff;\n    font-size: 1rem;\n    font-weight: 500;\n    line-height: 1;\n    cursor: pointer;\n    transition: transform 0.2s ease, filter 0.2s ease, background 0.2s ease;\n}\n.product-offer-button.is-primary {\n    background: linear-gradient(180deg, #0d6efd, #0a57d5);\n    box-shadow: 0 18px 32px rgba(13, 110, 253, 0.28);\n}\n.product-offer-button.is-secondary {\n    border: 1px solid rgba(255, 255, 255, 0.14);\n    background: linear-gradient(180deg, rgba(25, 27, 31, 0.96), rgba(18, 20, 24, 0.96));\n}\n.product-offer-button.is-wallet {\n    background: linear-gradient(180deg, #26b981, #12845c);\n    color: #ffffff;\n    box-shadow: 0 18px 32px rgba(18, 132, 92, 0.22);\n}\n.product-related-section { padding: 8px 0 70px; }\n.container.product-related-container {\n    width: min(1460px, calc(100vw - 36px));\n}\n.product-related-header {\n    padding-top: 18px;\n    margin-bottom: 18px;\n}\n.product-related-title {\n    margin: 0;\n    color: #f4f8fc;\n    font-size: clamp(1.55rem, 2vw, 2.05rem);\n    font-weight: 850;\n    line-height: 1.2;\n}\n.product-related-carousel {\n    position: relative;\n    padding: 18px;\n    border: 1px solid #263b53;\n    background: linear-gradient(180deg, rgba(22, 34, 48, 0.74), rgba(13, 22, 32, 0.8));\n    box-shadow: inset 0 1px rgba(255, 255, 255, 0.04);\n}\n.product-related-nav {\n    position: absolute;\n    top: 50%;\n    z-index: 5;\n    width: 38px;\n    height: 64px;\n    border: 1px solid rgba(83, 125, 158, 0.34);\n    border-radius: 3px;\n    background: rgba(4, 12, 19, 0.78);\n    color: #d8efff;\n    font-size: 1.5rem;\n    transform: translateY(-50%);\n}\n.product-related-nav:hover,\n.product-related-nav:focus-visible {\n    transform: translateY(-50%);\n    background: rgba(20, 51, 73, 0.94);\n}\n.product-related-nav--prev {\n    left: 4px;\n}\n.product-related-nav--next {\n    right: 4px;\n}\n.product-related-viewport {\n    width: 100%;\n    padding: 1px 0;\n    scroll-behavior: auto;\n    overscroll-behavior-x: contain;\n}\n.product-related-track {\n    display: flex;\n    gap: 16px;\n    width: max-content;\n    min-width: 100%;\n}\n.product-related-card {\n    flex: 0 0 clamp(360px, 29vw, 420px);\n    aspect-ratio: 16 / 9;\n}\n.product-related-link {\n    position: relative;\n    display: block;\n    width: 100%;\n    height: 100%;\n    padding: 0;\n    text-align: left;\n    border: 1px solid rgba(74, 105, 136, 0.34);\n    border-radius: 4px;\n    overflow: hidden;\n    background: #0d1722;\n    color: inherit;\n    cursor: pointer;\n    box-shadow: 0 18px 26px rgba(0, 0, 0, 0.45);\n    transition: transform 0.18s ease, border-color 0.18s ease, filter 0.18s ease;\n}\n.product-related-link:hover,\n.product-related-link:focus-visible {\n    transform: translateY(-3px);\n    border-color: rgba(67, 143, 202, 0.62);\n    filter: brightness(1.06);\n    outline: none;\n}\n.product-related-poster {\n    position: relative;\n    width: 100%;\n    height: 100%;\n    overflow: hidden;\n    background: #0b0e13;\n}\n.product-related-badge {\n    position: absolute;\n    top: 11px;\n    left: 12px;\n    z-index: 3;\n    padding: 7px 10px;\n    border: 1px solid rgba(91, 128, 157, 0.34);\n    border-radius: 3px;\n    background: rgba(5, 12, 19, 0.9);\n    color: #ffffff;\n    font-size: 0.78rem;\n    font-weight: 850;\n}\n.product-related-poster img {\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n    transition: transform 0.35s ease, filter 0.35s ease;\n}\n.product-related-link:hover .product-related-poster img,\n.product-related-link:focus-visible .product-related-poster img {\n    transform: scale(1.025);\n    filter: saturate(1.05) contrast(1.03);\n}\n.product-related-shade {\n    position: absolute;\n    inset: 0;\n    z-index: 1;\n    background:\n        linear-g