	private static string BuildHomeHeaderStyles()
	{
		return "\nbody.has-home-header {\n    padding: 0 0 48px;\n}\nbody.has-home-header .product-page-main {\n    padding: 14px 18px 0;\n}\nbutton,\n[data-host-action] {\n    cursor: pointer;\n}\n.top-chrome {\n    --cyan: #27d9ff;\n    position: sticky;\n    top: 0;\n    z-index: 200;\n    background: linear-gradient(180deg, rgba(9, 13, 19, 0.98), rgba(8, 13, 20, 0.94));\n    border-bottom: 1px solid rgba(75, 95, 120, 0.22);\n    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.36);\n}\n.utility-row,\n.main-row {\n    display: grid;\n    align-items: center;\n    gap: clamp(10px, 1.1vw, 18px);\n    padding-inline: clamp(14px, 1.25vw, 22px);\n}\n.utility-row {\n    position: relative;\n    z-index: 2;\n    grid-template-columns: minmax(0, 1fr) auto;\n    height: 54px;\n}\n.utility-left,\n.utility-right,\n.primary-nav,\n.account-cluster,\n.window-controls {\n    display: flex;\n    align-items: center;\n}\n.utility-left {\n    gap: clamp(8px, 0.75vw, 12px);\n    min-width: 0;\n}\n.utility-right {\n    justify-self: end;\n    gap: clamp(8px, 0.85vw, 14px);\n    min-width: 0;\n}\n.window-controls {\n    gap: clamp(5px, 0.5vw, 8px);\n}\n.brand-word,\n.window-button,\n.nav-item,\n.cart-pill,\n.user-chip {\n    border: 0;\n    background: transparent;\n    white-space: nowrap;\n}\n.brand-word {\n    min-width: 0;\n    display: inline-flex;\n    align-items: center;\n    gap: 10px;\n    padding: 0;\n    color: #f5f8fc;\n}\n.brand-word img {\n    width: 32px;\n    height: 36px;\n    object-fit: contain;\n    flex: 0 0 auto;\n}\n.brand-word strong {\n    font-size: 18px;\n    font-weight: 900;\n    letter-spacing: 0.02em;\n}\n.window-button {\n    width: clamp(30px, 2vw, 36px);\n    height: 28px;\n    border-radius: 4px;\n    color: #d6deeb;\n    font-size: 13px;\n}\n.window-button:hover {\n    background: rgba(255, 255, 255, 0.08);\n}\n.window-button.is-close:hover {\n    background: #c83232;\n    color: #ffffff;\n}\n.main-row {\n    position: relative;\n    z-index: 1;\n    grid-templa