tton:hover,\n.account-menu-items button:focus-visible {\n    background: rgba(55, 112, 151, 0.32);\n    color: #ffffff;\n    outline: none;\n}\n.account-menu-items button > span:last-child {\n    min-width: 0;\n    display: grid;\n    gap: 2px;\n}\n.account-menu-items strong {\n    color: inherit;\n    font-size: 12px;\n    font-weight: 800;\n}\n.account-menu-items small {\n    color: #7f98aa;\n    font-size: 10px;\n}\n.account-menu-icon {\n    width: 28px;\n    height: 28px;\n    display: grid;\n    place-items: center;\n    border: 1px solid rgba(102, 192, 244, 0.22);\n    border-radius: 3px;\n    background: rgba(102, 192, 244, 0.08);\n    color: #8ed4ff;\n    font-size: 16px;\n    font-weight: 800;\n}\n.account-menu-icon--user {\n    position: relative;\n}\n.account-menu-icon--user::before {\n    content: \"\";\n    width: 7px;\n    height: 7px;\n    border: 2px solid #8ed4ff;\n    border-radius: 50%;\n}\n.account-menu-icon--user::after {\n    content: \"\";\n    position: absolute;\n    left: 7px;\n    right: 7px;\n    bottom: 5px;\n    height: 6px;\n    border: 2px solid #8ed4ff;\n    border-bottom: 0;\n    border-radius: 7px 7px 0 0;\n}\n.account-menu-footer {\n    padding: 7px;\n    border-top: 1px solid rgba(102, 192, 244, 0.1);\n}\n.account-menu-signout {\n    min-height: 40px;\n    color: #ff9d9d;\n    font-size: 12px;\n    font-weight: 800;\n}\n.account-menu-signout .account-menu-icon {\n    border-color: rgba(255, 104, 104, 0.2);\n    background: rgba(255, 83, 83, 0.07);\n    color: #ff9d9d;\n}\n.account-menu-signout:hover,\n.account-menu-signout:focus-visible {\n    background: rgba(167, 44, 44, 0.22);\n    color: #ffd0d0;\n    outline: none;\n}\n.search-box {\n    display: grid;\n    grid-template-columns: minmax(0, 1fr) 42px;\n    justify-self: end;\n    width: min(460px, 100%);\n    height: 38px;\n}\n.search-box input {\n    min-width: 0;\n    border: 1px solid #3a434f;\n    border-right: 0;\n    border-radius: 4px 0 0 4px;\n    background: #333840;