				StoreProductEdition storeProductEdition = data.Editions[i];
				string value = BuildEditionChipName(storeProductEdition, i);
				string value2 = (string.IsNullOrWhiteSpace(storeProductEdition.PriceText) ? storeProductEdition.CurrentPriceText : storeProductEdition.PriceText);
				StringBuilder stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder4 = stringBuilder2;
				StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(267, 9, stringBuilder2);
				handler.AppendLiteral("<button class=\"product-edition-chip");
				handler.AppendFormatted(storeProductEdition.IsActive ? " is-active" : string.Empty);
				handler.AppendLiteral("\" type=\"button\" data-edition-option data-edition-index=\"");
				handler.AppendFormatted(i);
				handler.AppendLiteral("\" data-edition-note=\"");
				handler.AppendFormatted(EncodeAttribute(storeProductEdition.Note));
				handler.AppendLiteral("\" data-edition-current-price=\"");
				handler.AppendFormatted(EncodeAttribute(storeProductEdition.CurrentPriceText));
				handler.AppendLiteral("\" data-edition-reference-price=\"");
				handler.AppendFormatted(EncodeAttribute(storeProductEdition.ReferencePriceText));
				handler.AppendLiteral("\" data-edition-discount=\"");
				handler.AppendFormatted(EncodeAttribute(storeProductEdition.DiscountText));
