	private static string BuildEditionChipName(StoreProductEdition edition, int index)
	{
		return ExtractGeneratedEditionName(string.IsNullOrWhiteSpace(edition.Name) ? $"Phiên bản {index + 1}" : edition.Name.Trim()).ToUpperInvariant();
	}

	private static string ExtractGeneratedEditionName(string value)
	{
		string text = value.Trim();
		string text2 = text.ToLowerInvariant();
		int num = (text2.StartsWith("phiên bản ", StringComparison.Ordinal) ? "phiên bản ".Length : (text2.StartsWith("phien ban ", StringComparison.Ordinal) ? "phien ban ".Length : 0));
		if (num == 0)
		{
			return text;
		}
		int num2 = IndexOfAnyPhrase(text2, num, " dành cho ", " danh cho ", " đang áp dụng ", " dang ap dung ", " giá ", " gia ", ",");
		string text3;
		if (num2 <= num)
		{
			text3 = text.Substring(num);
		}
		else
		{
			int num3 = num;
			text3 = text.Substring(num3, num2 - num3);
		}
		string text4 = text3;
		if (!string.IsNullOrWhiteSpace(text4))
		{
			return text4.Trim();
		}
		return text;
	}

	private static int IndexOfAnyPhrase(string value, int startIndex, params string[] phrases)
	{
		int num = -1;
		foreach (string value2 in phrases)
		{
			int num2 = value.IndexOf(value2, startIndex, StringComparison.Ordinal);
			if (num2 >= 0 && (num < 0 || num2 < num))
			{
				num = num2;
			}
		}
		return num;
	}

	private static string BuildPackageSection(IReadOnlyList<string> items)
	{
		if (items.Count == 0)
		{
			return string.Empty;
		}
		StringBuilder stringBuilder = new StringBuilder();
		foreach (string item in items)
		{
			StringBuilder stringBuilder2 = stringBuilder;
			StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(73, 1, stringBuilder2);
			handler.AppendLiteral("<li>\n    <span aria-hidden=\"true\">&#10003;</span>\n    <span>");
			handler.AppendFormatted(EncodeText(item));
			handler.AppendLiteral("</span>\n</li>");
			stringBuilder2.Append(ref handler);
		}
		return $"<article class=\"product-package-card product-package-card--purchase\" aria-labelledby=\"purchaseInfoTitle\">\n    <h2 id=\"purchaseInfoTitle\" class=\"product-package-title\">Thông tin gói mua</h2>\n    <ul class=\"product-package-list\">\n        {stringBuilder}\n    </ul>\n</article>";
	}

	private static string BuildOverviewSection(string title, string? html, string? text, string? modifierClass)
	{
		string value = BuildRichContent(html, text);
		if (string.IsNullOrWhiteSpace(value))
		{
			return string.Empty;
		}
		string value2 = (string.IsNullOrWhiteSpace(modifierClass) ? "product-package-card storefront-rich-card product-overview-card" : ("product-package-card storefront-rich-card product-overview-card " + modifierClass));
