	private static string BuildScript()
	{
		return "(() => {\n    const root = document.querySelector('[data-detail-root]');\n    if (!root) {\n        return;\n    }\n\n    const post = (message) => {\n        if (window.chrome && window.chrome.webview) {\n            window.chrome.webview.postMessage(message);\n        }\n    };\n\n    const accountToggle = document.querySelector('[data-account-toggle]');\n    const accountMenu = document.querySelector('[data-account-menu]');\n    const cartPill = document.querySelector('.cart-pill');\n    const detailToastHost = document.querySelector('[data-detail-toast-host]');\n    const orderCheckoutModal = document.querySelector('[data-order-checkout-modal]');\n    const orderCheckoutQr = document.querySelector('[data-order-checkout-qr]');\n    const orderCheckoutQrEmpty = document.querySelector('[data-order-checkout-qr-empty]');\n    const orderCheckoutWalletSuccess = document.querySelector('[data-order-checkout-wallet-success]');\n    const orderCheckoutItems = document.querySelector('[data-order-checkout-items]');\n    const orderCheckoutRefresh = document.querySelector('[data-order-checkout-refresh]');\n    const orderCheckoutConfirm = document.querySelector('[data-order-checkout-confirm]');\n    const orderCheckoutWallet = document.querySelector('[data-order-checkout-wallet]');\n    const orderCheckoutTransferSection = document.querySelector('[data-order-checkout-transfer-section]');\n    const orderWalletConfirm = document.querySelector('[data-order-wallet-confirm]');\n    const orderWalletConfirmTotal = document.querySelector('[data-order-wallet-confirm-total]');\n    const orderWalletConfirmCode = document.querySelector('[data-order-wallet-confirm-code]');\n    const orderWalletConfirmSubmit = document.querySelector('[data-order-wallet-confirm-submit]');\n    let activeOrderCheckoutCode = '';\n    let orderCheckoutPollTimer = 0;\n\n    function setAccountMenuOpen(isOpen) {\n        if (!accountToggle || !accountMenu) {\n            return;\n        }\n\n        accountMenu.hidden = !isOpen;\n        accountToggle.classList.toggle('is-open', isOpen);\n        accountToggle.setAttribute('aria-expanded', String(isOpen));\n\n        if (isOpen) {\n            accountMenu.querySelector('[role=\"menuitem\"]')?.focus({ preventScroll: true });\n        }\n    }\n\n    function isHeaderInteractive(target) {\n        return Boolean(target.closest('button, input, textarea, select, a, [data-host-action]'));\n    }\n\n    function animateCartFly(sourceButton) {\n        if (!sourceButton || !cartPill) {\n            return;\n        }\n\n        const image = document.querySelector('.product-gallery-main-image') ||\n            document.querySelector('.product-summary-cover img');\n        const source = image || sourceButton;\n        const sourceRect = source.getBoundingClientRect();\n        const targetRect = cartPill.getBoundingClientRect();\n        if (!sourceRect.width || !sourceRect.height || !targetRect.width || !targetRect.height) {\n            return;\n        }\n\n        const flyer = document.createElement('div');\n        flyer.className = 'cart-flyer';\n        flyer.style.left = `${sourceRect.left}px`;\n        flyer.style.top = `${sourceRect.top}px`;\n        flyer.style.width = `${Math.min(sourceRect.width, 88)}px`;\n        flyer.style.height = `${Math.min(sourceRect.height, 62)}px`;\n\n        if (image?.currentSrc || image?.src) {\n            const cloneImage = document.createElement('img');\n            cloneImage.src = image.currentSrc || image.src;\n            cloneImage.alt = '';\n            flyer.append(cloneImage);\n        }\n\n        document.body.append(flyer);\n        const flyerRect = flyer.getBoundingClientRect();\n        const startX = sourceRect.left + sourceRect.width / 2 - (flyerRect.left + flyerRect.width / 2);\n        const startY = sourceRect.top + sourceRect.height / 2 - (flyerRect.top + flyerRect.height / 2);\n        const endX = targetRect.left + targetRect.width / 2 - (flyerRec