ets the thumbnails\n        // use the full gallery width whenever they already fit in one row.\n        [thumbPrevButton, thumbNextButton].forEach((button) => {\n            if (button) {\n                button.hidden = true;\n            }\n        });\n\n        const needsNavigation = thumbViewport.scrollWidth > thumbViewport.clientWidth + 2;\n\n        [thumbPrevButton, thumbNextButton].forEach((button) => {\n            if (button) {\n                button.hidden = !needsNavigation;\n            }\n        });\n\n        if (!needsNavigation) {\n            thumbViewport.scrollLeft = 0;\n        }\n\n        if (thumbShell) {\n            thumbShell.dataset.hasOverflow = String(needsNavigation);\n        }\n    };\n\n    const clearGalleryAuto = () => {\n        if (galleryAutoTimer) {\n            window.clearTimeout(galleryAutoTimer);\n            galleryAutoTimer = 0;\n        }\n    };\n\n    const scheduleGalleryAuto = () => {\n        clearGalleryAuto();\n\n        if (galleryAutoStopped || galleryThumbs.length <= 1 || document.hidden) {\n            return;\n        }\n\n        galleryAutoTimer = window.setTimeout(() => {\n            galleryAutoTimer = 0;\n            applyGallery(galleryIndex + 1, { auto: true });\n        }, galleryAutoDelay);\n    };\n\n    const stopGalleryAuto = () => {\n        galleryAutoStopped = true;\n        clearGalleryAuto();\n    };\n\n    const scrollActiveThumbIntoView = (thumb, behavior = 'smooth') => {\n        if (!thumbViewport || thumbViewport.clientWidth <= 0) {\n            return;\n        }\n\n        const viewportLeft = thumbViewport.scrollLeft;\n        const viewportRight = viewportLeft + thumbViewport.clientWidth;\n        const thumbLeft = thumb.offsetLeft;\n        const thumbRight = thumbLeft + thumb.offsetWidth;\n        let nextScrollLeft = viewportLeft;\n\n        if (thumbLeft < viewportLeft) {\n            nextScrollLeft = thumbLeft;\n        } else if (thumbRight > viewportRight) {\n           