vigation);\n    galleryThumbs.forEach((thumb) => {\n        thumb.querySelector('img')?.addEventListener('load', updateThumbnailNavigation);\n    });\n\n    const thumbScrollAmount = () => {\n        if (!thumbViewport) {\n            return 240;\n        }\n\n        return Math.max(thumbViewport.clientWidth * 0.78, 240);\n    };\n\n    if (thumbPrevButton && thumbViewport) {\n        thumbPrevButton.addEventListener('click', () => {\n            stopGalleryAuto();\n            thumbViewport.scrollBy({ left: -thumbScrollAmount(), behavior: 'smooth' });\n        });\n    }\n\n    if (thumbNextButton && thumbViewport) {\n        thumbNextButton.addEventListener('click', () => {\n            stopGalleryAuto();\n            thumbViewport.scrollBy({ left: thumbScrollAmount(), behavior: 'smooth' });\n        });\n    }\n\n    if (galleryThumbs.length > 0) {\n        applyGallery(0, { immediate: true });\n    }\n\n    document.addEventListener('visibilitychange', () => {\n        if (document.hidden) {\n            clearGalleryAuto();\n            return;\n        }\n\n        scheduleGalleryAuto();\n    });\n\n    const editionSwitcher = document.querySelector('[data-edition-switcher]');\n    const editionButtons = Array.from(editionSwitcher?.querySelectorAll('[data-edition-option]') || []);\n    const noteElement = editionSwitcher?.querySelector('[data-edition-note-output]');\n    const currentPriceElement = editionSwitcher?.querySelector('[data-edition-price-current]');\n    const referencePriceElement = editionSwitcher?.querySelector('[data-edition-price-reference]');\n    const discountPriceElement = editionSwitcher?.querySelector('[data-edition-price-discount]');\n    const cartButtons = Array.from(editionSwitcher?.querySelectorAll('[data-cart-trigger]') || []);\n\n    let activeEditionIndex = Number.parseInt(root.dataset.initialEdition || '0', 10);\n    if (Number.isNaN(activeEditionIndex)) {\n        activeEditionIndex = 0;\n    }\n\n    const applyEdition = (index) => {\n        if (editionButtons.length === 0) {\n            return;\n        }\n\n        activeEditionIndex = Math.max(0, Math.min(index, editionButtons.length - 1));\n\n        editionButtons.forEach((button, buttonIndex) => {\n            const isActive = buttonIndex === activeEditionIndex;\n            button.classList.toggle('is-active', isActive);\n            button.setAttribute('aria-pressed', isActive ? 'true' : 'false');\n        });\n\n        const activeButton = editionButtons[activeEditionIndex];\n        if (noteElement) {\n            noteElement.textContent = activeButton.dataset.editionNote || '';\n        }\n\n        if (currentPriceElement) {\n            currentPriceElement.textContent = activeButton.dataset.editionCurrentPrice || currentPriceElement.textContent;\n        }\n\n        setHiddenByValue(referencePriceElement, activeButton.dataset.editionReferencePrice);\n        setHiddenByValue(discountPriceElement, activeButton.dataset.editionDiscount);\n    };\n\n    editionButtons.forEach((button, index) => {\n        button.addEventListener('click', () => applyEdition(index));\n    });\n\n    if (editionButtons.length > 0) {\n        applyEdition(activeEditionIndex);\n    }\n\n    cartButtons.forEach((button) => {\n        button.addEventListener('click', () => {\n            if (button.disabled) {\n                return;\n            }\n\n            const action = button.dataset.cartAction === 'buy' ? 'buy' : 'cart';\n            const checkout = action === 'buy' || button.dataset.checkout === '1' ? '1' : '0';\n            const paymentMethod = button.dataset.paymentMethod === 'wallet' ? ':wallet' : '';\n            if (checkout === '0' && !paymentMethod) {\n                animateCartFly(button);\n            }\n            cartButtons.forEach(item => item.disabled = true);\n            post(`cart:${activeEditionIndex}:${checkout}${paymentMethod}`);\n            window.setTimeout(() => {\n                cartButtons.forEach(item => item.disabled = false);\n            }, 1800);\n        });\n    });\n\n    document.querySelectorAll('[data-order-checkout-close]').forEach((button) => {\n        button.addEventListener('click', () => closeOrderCheckoutPopup(false));\n    });\n\n    orderCheckoutRefresh?.addEventListener('click', () => {\n        if (!activeOrderCheckoutCode) {\n            return;\n        }\n\n        orderCheckoutRefresh.disabled = true;\n        orderCheckoutRefresh.textContent = 'Đang kiểm tra...';\n        post({ type: 'refreshOrderCheckoutStatus', orderCode: activeOrderCheckoutCode });\n    });\n\n    orderCheckoutWallet?.addEventListener('click', () => {\n        openOrderWalletConfirm();\n    });\n\n    document.querySelectorAll('[data-order-wallet-confirm-cancel]').forEach((button) => {\n        button.addEventListener('click', () => closeOrderWalletConfirm());\n    });\n\n    orderWalletConfirmSubmit?.addEventListener('click', () => {\n        if (!activeOrderCheckoutCode) {\n            return;\n        }\n\n        setOrderWalletConfirmBusy(true);\n        closeOrderWalletConfirm();\n        post({ type: 'payOrderCheckoutWithWallet', orderCode: activeOrderCheckoutCode });\n    });\n\n    orderCheckoutConfirm?.addEventListener('click', () => closeOrderCheckoutPopup(true));\n\n    const reviewForm = document.querySelector('[data-review-form]');\n    const reviewLoadingOverlay = document.querySelector('[data-review-loading]');\n    const reviewLoadingRating = document.querySelector('[data-review-loading-rating]');\n    const setReviewSubmitting = (isSubmitting, rating = '') => {\n        document.body.classList.toggle('review-submitting', isSubmitting);\n        if (reviewLoadingOverlay) {\n            reviewLoadingOverlay.hidden = !isSubmitting;\n        }\n        if (reviewLoadingRating) {\n            reviewLoadingRating.textContent = rating ? `${rating} sao` : '';\n        }\n\n        if (isSubmitting) {\n            reviewLoadingOverlay?.querySelector('.review-loading-dialog')?.focus?.();\n        }\n    };\n\n    window.__nestgReview = {\n        finish: () => setReviewSubmitting(false)\n    };\n\n    if (reviewForm) {\n        reviewForm.addEventListener('submit', (event) => {\n            event.preventDefault();\n\n            const formData = new FormData(reviewForm);\n            const rating = getString(formData.get('Rating')).trim();\n            const reviewText = getString(formData.get('ReviewText')).trim();\n            if (!rating) {\n                return;\n            }\n\n            const submitButton = reviewForm.querySelector('[data-review-submit]');\n            if (submitButton) {\n                submitButton.disabled = true;\n                submitButton.textContent = 'Đang gửi...';\n            }\n            setReviewSubmitting(true, rating);\n\n            const scrollY = Math.max(0, Math.round(window.scrollY || document.documentElement.scrollTop || 0));\n            post(`review:${rating}:${scrollY}:${encodeURIComponent(reviewText)}`);\n        });\n    }\n\n    const websiteButton = document.querySelector('[data-open-website]');\n    if (websiteButton) {\n        websiteButton.addEventListener('click', () => {\n            const url = websiteButton.dataset.openWebsite;\n            if (url) {\n                post(`open:${encodeURIComponent(url)}`);\n            }\n        });\n    }\n\n    document.querySelectorAll('[data-detail-back]').forEach((button) => {\n        button.addEventListener('click', () => post('backHome'));\n    });\n\n    document.addEventListener('pointerdown', (event) => {\n        const target = event.target instanceof Element ? event.target : null;\n        if (!target || isHeaderInteractive(target)) {\n            return;\n        }\n\n        if (target.closest('[data-drag-region]')) {\n            post({ type: 'dragWindow' });\n        }\n    });\n\n    document.addEventListener('click', (event) => {\n        const target = event.target instanceof Element ? event.target : null;\n        if (!target) {\n            return;\n        }\n\n        if (target.closest('[data-account-toggle]')) {\n            event.preventDefault();\n            event.stopPropagation();\n            setAccountMenuOpen(Boolean(accountMenu?.hidden));\n            return;\n        }\n\n        if (!target.closest('[data-account-menu]')) {\n            setAccountMenuOpen(false);\n        }\n\n        const hostAction = target.closest('[data-host-action]');\n        if (!hostAction) {\n            return;\n        }\n\n        event.preventDefault();\n        event.stopPropagation();\n\n        const action = hostAction.getAttribute('data-host-action');\n        setAccountMenuOpen(false);\n        if (!action) {\n            return;\n        }\n\n        if (action === 'backHome') {\n            post('backHome');\n            return;\n        }\n\n        post({ type: action });\n    });\n\n    document.addEventListener('keydown', (event) => {\n        if (event.key === 'Escape') {\n            setAccountMenuOpen(false);\n        }\n    });\n\n    const relatedViewport = document.querySelector('[data-related-viewport]');\n    const relatedTrack = relatedViewport?.querySelector('.product-related-track');\n    const relatedPrev = document.querySelector('[data-related-prev]');\n    const relatedNext = document.querySelector('[data-related-next]');\n    let relatedLoopWidth = 0;\n    let relatedAutoPosition = 0;\n    let relatedPaused = false;\n    let relatedLastFrameTime = 0;\n    let relatedResumeTimer = 0;\n\n    relatedViewport?.addEventListener('click', (event) => {\n        const target = event.target instanceof Element\n            ? event.target.closest('[data-related-game]')\n            : null;\n        const gameId = target?.getAttribute('data-related-game');\n        if (gameId) {\n            post(`game:${gameId}`);\n        }\n    });\n\n    const setRelatedPaused = (value) => {\n        relatedPaused = value;\n        relatedLastFrameTime = 0;\n        if (relatedViewport) {\n            relatedAutoPosition = relatedViewport.scrollLeft;\n        }\n    };\n\n    const normalizeRelatedLoopPosition = () => {\n        if (!relatedViewport || relatedLoopWidth <= 0) {\n            return;\n        }\n\n        while (relatedViewport.scrollLeft >= relatedLoopWidth) {\n            relatedViewport.scrollLeft -= relatedLoopWidth;\n        }\n        while (relatedViewport.scrollLeft < 0) {\n            relatedViewport.scrollLeft += relatedLoopWidth;\n        }\n\n        relatedAutoPosition = relatedViewport.scrollLeft;\n    };\n\n    const refreshRelatedLoopMetrics = () => {\n        if (!relatedViewport || !relatedTrack) {\n            return;\n        }\n\n        const firstOriginal = relatedTrack.querySelector('.product-related-card:not([data-loop-clone])');\n        const firstClone = relatedTrack.querySelector('.product-related-card[data-loop-clone]');\n        relatedLoopWidth = firstOriginal && firstClone\n            ? Math.max(0, firstClone.offsetLeft - firstOriginal.offsetLeft)\n            : 0;\n        relatedViewport.dataset.loopWidth = String(relatedLoopWidth);\n        normalizeRelatedLoopPosition();\n    };\n\n    const pauseRelatedBriefly = (delay = 1800) => {\n        setRelatedPaused(true);\n        window.clearTimeout(relatedResumeTimer);\n        relatedResumeTimer = window.setTimeout(() => {\n            normalizeRelatedLoopPosition();\n            setRelatedPaused(false);\n        }, delay);\n    };\n\n    const canAutoScrollRelated = () =>\n        Boolean(relatedViewport) &&\n        relatedLoopWidth > relatedViewport.clientWidth + 4;\n\n    const animateRelatedProducts = (now) => {\n        if (!relatedLastFrameTime) {\n            relatedLastFrameTime = now;\n        }\n\n        const elapsed = Math.min(80, now - relatedLastFrameTime);\n        relatedLastFrameTime = now;\n\n        if (relatedViewport && !relatedPaused && canAutoScrollRelated()) {\n            relatedAutoPosition += 46 * elapsed / 1000;\n            if (relatedAutoPosition >= relatedLoopWidth) {\n                relatedAutoPosition -= relatedLoopWidth;\n            }\n            relatedViewport.scrollLeft = relatedAutoPosition;\n        }\n\n        window.requestAnimationFrame(animateRelatedProducts);\n    };\n\n    if (relatedViewport && relatedTrack) {\n        const originals = Array.from(\n            relatedTrack.querySelectorAll('.product-related-card:not([data-loop-clone])'));\n\n        if (originals.length > 1) {\n            originals.forEach((card, index) => {\n                const clone = card.cloneNode(true);\n                clone.setAttribute('data-loop-clone', 'true');\n                clone.setAttribute('data-loop-source', String(index));\n                clone.setAttribute('aria-hidden', 'true');\n                clone.querySelector('[data-related-game]')?.setAttribute('tabindex', '-1');\n                relatedTrack.append(clone);\n            });\n\n            relatedViewport.addEventListener('pointerenter', () => setRelatedPaused(true));\n            relatedViewport.addEventListener('pointerleave', () => setRelatedPaused(false));\n            relatedViewport.addEventListener('focusin', () => setRelatedPaused(true));\n            relatedViewport.addEventListener('focusout', (event) => {\n                if (!relatedViewport.contains(event.relatedTarget)) {\n                    setRelatedPaused(false);\n                }\n            });\n            relatedViewport.addEventListener('pointerdown', () => pauseRelatedBriefly());\n            relatedViewport.addEventListener('wheel', () => pauseRelatedBriefly(), { passive: true });\n            window.addEventListener('resize', () => window.setTimeout(refreshRelatedLoopMetrics, 100));\n            document.addEventListener('visibilitychange', () => setRelatedPaused(document.hidden));\n\n            relatedTrack.querySelectorAll('img').forEach((image) => {\n                image.addEventListener('load', refreshRelatedLoopMetrics, { once: true });\n            });\n\n            window.requestAnimationFrame(refreshRelatedLoopMetrics);\n            window.setTimeout(refreshRelatedLoopMetrics, 180);\n            window.setTimeout(refreshRelatedLoopMetrics, 700);\n            window.requestAnimationFrame(animateRelatedProducts);\n        }\n    }\n\n    const relatedScrollAmount = () => {\n        if (!relatedViewport) {\n            return 320;\n        }\n\n        return Math.max(relatedViewport.clientWidth * 0.8, 240);\n    };\n\n    if (relatedViewport && relatedPrev) {\n        relatedPrev.addEventListener('click', () => {\n            pauseRelatedBriefly();\n            if (relatedLoopWidth > 0 && relatedViewport.scrollLeft <= 2) {\n                relatedViewport.scrollLeft = relatedLoopWidth;\n            }\n            relatedViewport.scrollBy({ left: -relatedScrollAmount(), behavior: 'smooth' });\n        });\n    }\n\n    if (relatedViewport && relatedNext) {\n        relatedNext.addEventListener('click', () => {\n            pauseRelatedBriefly();\n            relatedViewport.scrollBy({ left: relatedScrollAmount(), behavior: 'smooth' });\n        });\n    }\n\n    const collapsedHeight = (() => {\n        const value = getComputedStyle(document.documentElement).getPropertyValue('--overview-collapsed-height');\n        const parsed = Number.parseFloat(value);\n        return Number.isFinite(parsed) ? parsed : 320;\n    })();\n\n    document.querySelectorAll('[data-overview-card]').forEach((card) => {\n        const content = card.querySelector('[data-overview-content]');\n        const toggle = card.querySelector('[data-overview-toggle]');\n        if (!content || !toggle) {\n            return;\n        }\n\n        const applyExpansionState = () => {\n            const needsCollapse = content.scrollHeight > collapsedHeight + 28;\n            toggle.hidden = !needsCollapse;\n            if (!needsCollapse) {\n                content.classList.remove('is-collapsed');\n                toggle.setAttribute('aria-expanded', 'true');\n                return;\n            }\n\n            content.classList.add('is-collapsed');\n            toggle.setAttribute('aria-expanded', 'false');\n            toggle.textContent = 'Xem thêm';\n        };\n\n        requestAnimationFrame(applyExpansionState);\n\n        toggle.addEventListener('click', () => {\n            const willExpand = content.classList.contains('is-collapsed');\n            content.classList.toggle('is-collapsed', !willExpand);\n            toggle.setAttribute('aria-expanded', willExpand ? 'true' : 'false');\n            toggle.textContent = willExpand ? 'Thu gọn' : 'Xem thêm';\n        });\n    });\n})();";
