	private static string BuildRichContent(string? html, string? text)
	{
		string text2 = SanitizeHtml(html);
		if (!string.IsNullOrWhiteSpace(text2))
		{
			return text2;
		}
		if (!string.IsNullOrWhiteSpace(text))
		{
			return BuildPlainTextBlocks(text);
		}
		return string.Empty;
	}

	private static string BuildPlainTextBlocks(string text)
	{
		string[] array = text.Replace("\r", string.Empty).Split(new string[1] { "\n\n" }, StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
		if (array.Length == 0)
		{
			return "<p>" + EncodeText(text) + "</p>";
		}
		StringBuilder stringBuilder = new StringBuilder();
		string[] array2 = array;
		foreach (string value in array2)
		{
			stringBuilder.Append("<p>");
			stringBuilder.Append(EncodeText(value).Replace("\n", "<br />"));
			stringBuilder.Append("</p>");
		}
		return stringBuilder.ToString();
	}

	private static string SanitizeHtml(string? html)
	{
		if (string.IsNullOrWhiteSpace(html))
		{
			return string.Empty;
		}
		string input = ScriptTagPattern.Replace(html, string.Empty);
		input = StyleTagPattern.Replace(input, string.Empty);
		input = EventAttributePattern.Replace(input, string.Empty);
		input = ScriptProtocolPattern.Replace(input, string.Empty);
		return input.Trim();
	}

	private static string BuildRatingStars(decimal ratingValue)
	{
		StringBuilder stringBuilder = new StringBuilder();
		for (int i = 1; i <= 5; i++)
		{
			string value = ((ratingValue >= (decimal)i - 0.25m) ? " is-filled" : ((ratingValue >= (decimal)i - 0.75m) ? " is-half" : string.Empty));
			StringBuilder stringBuilder2 = stringBuilder;
			StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(33, 1, stringBuilder2);
			handler.AppendLiteral("<span class=\"star");
			handler.AppendFormatted(value);
			handler.AppendLiteral("\">&#9733;</span>");
			stringBuilder2.Append(ref handler);
		}
		return stringBuilder.ToString();
	}

	private static int GetActiveEditionIndex(StoreGameDetailData data)
	{
		StoreProductEdition activeEdition = data.GetActiveEdition();
		for (int i = 0; i < data.Editions.Count; i++)
		{
			if (data.Editions[i] == activeEdition)
			{
				return i;
			}
		}
		return 0;
	}

	private static string BuildHiddenAttribute(string? value)
	{
		if (!string.IsNullOrWhiteSpace(value))
		{
			return string.Empty;
		}
		return "hidden";
	}

	private static string EncodeText(string? value)
	{
		return WebUtility.HtmlEncode(value ?? string.Empty);
	}

	private static string EncodeAttribute(string? value)
	{
		return WebUtility.HtmlEncode(value ?? string.Empty);
	}
